import{_ as n,o as s,c as a,a as t}from"./app-2bc18e7d.js";const e={},p=t(`<h1 id="fibers" tabindex="-1"><a class="header-anchor" href="#fibers" aria-hidden="true">#</a> Fibers</h1><p>Buzz fibers are lightweight execution contexts inspired by Lua coroutines. Each fiber keeps its own call stack, local variables, and current execution state, which means buzz can pause an entire chain of function calls and later continue it exactly where it stopped. Because that switching is explicit and single-threaded, fibers are a simple way to pause and resume work, produce values one step at a time, and let the caller decide when execution continues, without callbacks or hand-written state machines.</p><h2 id="using-fibers" tabindex="-1"><a class="header-anchor" href="#using-fibers" aria-hidden="true">#</a> Using fibers</h2><p>You create a fiber by prefixing a function call with <code>&amp;</code>, and the wrapped call starts only when you <code>resume</code> it, <code>resolve</code> it, or iterate over it with <code>foreach</code>.</p><p>Functions that may suspend declare a yield type after <code>*&gt;</code>:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">fun</span> <span class="token function-definition function">work</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">str</span> <span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token keyword">int</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>That yield type is the type produced by <code>yield</code>, and it does not need to be nullable. What changes is how you call the function:</p><ul><li><code>work()</code> is a regular call. The function runs synchronously to completion.</li><li><code>&amp;work()</code> creates a <code>fib&lt;str, int&gt;</code> that you can drive manually.</li></ul><p>Because a fiber owns the whole call stack, a function can yield from any call depth. If <code>top()</code> calls <code>middle()</code>, which calls <code>bottom()</code>, a <code>yield</code> inside <code>bottom()</code> can suspend the fiber created from <code>&amp;top()</code>. As a consequence, a function needs a yield type in its signature not only when it uses <code>yield</code> directly, but also when it calls another function that might yield.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">import</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">buzz:std</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>

<span class="token keyword">fun</span> <span class="token function-definition function">leaf</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token keyword">int</span> <span class="token punctuation">{</span>
    _ <span class="token operator">=</span> <span class="token keyword">yield</span> <span class="token number">1</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">fun</span> <span class="token function-definition function">wrapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token keyword">int</span> <span class="token punctuation">{</span>
    <span class="token function">leaf</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">fun</span> <span class="token function-definition function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
    <span class="token keyword">var</span> <span class="token variable">sum</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>

    <span class="token keyword">foreach</span> <span class="token punctuation">(</span>n <span class="token keyword">in</span> <span class="token operator">&amp;</span><span class="token function">wrapper</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        sum <span class="token operator">+=</span> n<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span>sum <span class="token operator">==</span> <span class="token number">1</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">yield can happen deeper in the call stack</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If <code>wrapper()</code> were declared as <code>fun wrapper() &gt; void</code>, buzz would reject it because calling <code>leaf()</code> means <code>wrapper()</code> can also suspend when it runs inside a fiber.</p><h2 id="regular-call-or-fiber-call" tabindex="-1"><a class="header-anchor" href="#regular-call-or-fiber-call" aria-hidden="true">#</a> Regular Call Or Fiber Call</h2><p>A yieldable function can still be called like any other function. Without <code>&amp;</code>, each <code>yield</code> expression evaluates to its operand and execution continues immediately, so yielded values are discarded instead of being exposed to the caller.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">import</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">buzz:std</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>

<span class="token keyword">fun</span> <span class="token function-definition function">incrementAfterPause</span><span class="token punctuation">(</span>n<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">int</span> <span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token keyword">int</span> <span class="token punctuation">{</span>
    <span class="token keyword">final</span> <span class="token variable">value</span> <span class="token operator">=</span> <span class="token keyword">yield</span> n<span class="token punctuation">;</span>
    <span class="token keyword">return</span> value <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">fun</span> <span class="token function-definition function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token function">incrementAfterPause</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">3</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">regular calls stay synchronous</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">final</span> <span class="token variable">fiber</span> <span class="token operator">=</span> <span class="token operator">&amp;</span><span class="token function">incrementAfterPause</span><span class="token punctuation">(</span><span class="token number">7</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token keyword">resume</span> fiber <span class="token operator">==</span> <span class="token number">7</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">resume returns the yielded value</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token keyword">resume</span> fiber <span class="token operator">==</span> <span class="token null constant">null</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">completed fibers resume to null</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token keyword">resolve</span> fiber <span class="token operator">==</span> <span class="token number">8</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">resolve returns the final value</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span>fiber<span class="token punctuation">.</span><span class="token function">over</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">fiber is over</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>yield n</code> is an expression. When the function is running inside a fiber, <code>resume fiber</code> returns <code>n</code>, execution pauses, and when the fiber is resumed the whole expression evaluates to <code>n</code> inside the function. That is why <code>final value = yield n;</code> works.</p><h2 id="resume-and-resolve" tabindex="-1"><a class="header-anchor" href="#resume-and-resolve" aria-hidden="true">#</a> <code>resume</code> And <code>resolve</code></h2><p><code>resume fiber</code> advances the fiber until the next <code>yield</code> or until the function completes. Its type is always nullable because the fiber might finish without producing another yielded value:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">fiber</span> <span class="token operator">=</span> <span class="token operator">&amp;</span><span class="token function">incrementAfterPause</span><span class="token punctuation">(</span><span class="token number">7</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">resume</span> fiber<span class="token punctuation">;</span> <span class="token comment">// -&gt; 7</span>
<span class="token keyword">resume</span> fiber<span class="token punctuation">;</span> <span class="token comment">// -&gt; null</span>
</code></pre></div><p><code>resolve fiber</code> is different: it keeps running the fiber until the wrapped function returns, discards any yielded values along the way, and returns the function&#39;s return value. It can also be used after the fiber is already over to read that return value again.</p><h2 id="iterating-over-a-fiber" tabindex="-1"><a class="header-anchor" href="#iterating-over-a-fiber" aria-hidden="true">#</a> Iterating Over A Fiber</h2><p>Fibers are iterable. <code>foreach</code> repeatedly resumes the fiber until it is over and gives you each yielded value:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">import</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">buzz:std</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>

<span class="token keyword">fun</span> <span class="token function-definition function">numbers</span><span class="token punctuation">(</span>limit<span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token keyword">int</span> <span class="token punctuation">{</span>
    <span class="token keyword">foreach</span> <span class="token punctuation">(</span>n <span class="token keyword">in</span> <span class="token number">0</span><span class="token operator">..</span>limit<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        _ <span class="token operator">=</span> <span class="token keyword">yield</span> n<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token keyword">fun</span> <span class="token function-definition function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
    <span class="token keyword">var</span> <span class="token variable">sum</span> <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>

    <span class="token keyword">foreach</span> <span class="token punctuation">(</span>n <span class="token keyword">in</span> <span class="token operator">&amp;</span><span class="token function">numbers</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        sum <span class="token operator">+=</span> n<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span>sum <span class="token operator">==</span> <span class="token number">6</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">fiber iteration visits each yielded value</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This is often the simplest way to consume a fiber when you only care about its yielded values.</p><h2 id="inspecting-the-current-fiber" tabindex="-1"><a class="header-anchor" href="#inspecting-the-current-fiber" aria-hidden="true">#</a> Inspecting The Current Fiber</h2><p>Inside a running fiber, <code>std\\currentFiber()</code> returns the active fiber, and <code>fiber.isMain()</code> tells you whether it is the main fiber:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">import</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">buzz:std</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>

<span class="token keyword">fun</span> <span class="token function-definition function">inspect</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">currentFiber</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">is</span> <span class="token keyword">fib</span><span class="token operator">&lt;</span><span class="token keyword">void</span><span class="token punctuation">,</span> <span class="token keyword">void</span><span class="token operator">&gt;</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">current fiber is available</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token operator">!</span><span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">currentFiber</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">isMain</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">wrapped call is not the main fiber</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">fun</span> <span class="token function-definition function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token keyword">void</span> <span class="token punctuation">{</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">assert</span><span class="token punctuation">(</span><span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">currentFiber</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">isMain</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> message<span class="token punctuation">:</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">main runs in the main fiber</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    _ <span class="token operator">=</span> <span class="token keyword">resolve</span> <span class="token operator">&amp;</span><span class="token function">inspect</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>yield</code>, <code>resume</code>, and <code>resolve</code> are only valid inside function bodies. They are not allowed at the top level of a script.</p>`,27),o=[p];function c(u,i){return s(),a("div",null,o)}const r=n(e,[["render",c],["__file","fibers.html.vue"]]);export{r as default};
